        _ => "is-processing"
    };

    private static List<StudentModel> BuildStudents(string className, int total, int seed)
    {
        var list = new List<StudentModel>();
        for (var i = 1; i <= total; i++)
        {
            var published = i % 3 != 0;
            var status = published ? "Đã ban hành" : (i % 2 == 0 ? "Đang xử lý" : "Chờ ký");
            list.Add(new StudentModel
            {
                StudentCode = $"HS{seed:00}{i:000}",
                FullName = $"Học sinh {className} {i}",
                Note = published ? "Đã hoàn tất hồ sơ học bạ" : "Đang chờ hoàn thiện dữ liệu",
                Status = status
            });
        }
        return list;
    }

